// Do not edit this file as it will be overwritten if HAMR codegen is rerun

//! C-interface for the component.
//! This code must be unsafe.
//! Assumptions about correctness are introduced and need to be verified by other means.

use data::*;

#[cfg(test)]
use std::sync::Mutex;

#[cfg(not(test))]
extern "C" {
  fn get_actuationAuthority(value: *mut bool) -> bool;
  fn get_proposedRates(value: *mut FlightStack::ProposedActuatorRates) -> bool;
  fn put_actuatorCommand(value: *mut FlightStack::ActuatorCommand) -> bool;
}

pub fn unsafe_get_actuationAuthority() -> bool
{
  unsafe {
    let value: *mut bool = &mut false;
    get_actuationAuthority(value);
    return *value;
  }
}

pub fn unsafe_get_proposedRates() -> FlightStack::ProposedActuatorRates
{
  unsafe {
    let value: *mut FlightStack::ProposedActuatorRates = &mut FlightStack::ProposedActuatorRates::default();
    get_proposedRates(value);
    return *value;
  }
}

pub fn unsafe_put_actuatorCommand(value: &FlightStack::ActuatorCommand) -> bool
{
  unsafe {
    return put_actuatorCommand(value as *const FlightStack::ActuatorCommand as *mut FlightStack::ActuatorCommand);
  }
}

//////////////////////////////////////////////////////////////////////////////////
// Testing Versions
//////////////////////////////////////////////////////////////////////////////////

#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_actuationAuthority: Mutex<Option<bool>> = Mutex::new(None);
  pub static ref IN_proposedRates: Mutex<Option<FlightStack::ProposedActuatorRates>> = Mutex::new(None);
  pub static ref OUT_actuatorCommand: Mutex<Option<FlightStack::ActuatorCommand>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_actuationAuthority.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_proposedRates.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_actuatorCommand.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_actuationAuthority(value: *mut bool) -> bool
{
  unsafe {
    let guard = IN_actuationAuthority.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn get_proposedRates(value: *mut FlightStack::ProposedActuatorRates) -> bool
{
  unsafe {
    let guard = IN_proposedRates.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn put_actuatorCommand(value: *mut FlightStack::ActuatorCommand) -> bool
{
  unsafe {
    *OUT_actuatorCommand.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}
